1	export type Customer = {
2	  yearsWithMHPCO: number;
3	};
4	
5	export type Item = {
6	  type: string;
7	  material?: string;
8	  cursed?: boolean;
9	  enchantment?: number;
10	};
11	
12	const PROCESSING_FEE = 5;
13	
14	const COMPONENT_BASE_PREMIUM = 25;
15	
16	const BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: COMPONENT_BASE_PREMIUM,
22	  moonstone: COMPONENT_BASE_PREMIUM,
23	};
24	
25	const basePremiumFor = (type: string): number => {
26	  const basePremium = BASE_PREMIUMS[type];
27	  if (basePremium === undefined) {
28	    throw new Error(`Unknown item type: ${type}`);
29	  }
30	  return basePremium;
31	};
32	
33	const COMPONENT_BLOCK_PREMIUM = 60;
34	const COMPONENT_BLOCK_SIZE = 3;
35	
36	const countByType = (items: Item[]): Map<string, number> => {
37	  const counts = new Map<string, number>();
38	  for (const item of items) {
39	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
40	  }
41	  return counts;
42	};
43	
44	const premiumForGroup = (type: string, count: number): number => {
45	  const basePremium = basePremiumFor(type);
46	  const isComponentBlock =
47	    basePremium === COMPONENT_BASE_PREMIUM && count === COMPONENT_BLOCK_SIZE;
48	  if (isComponentBlock) {
49	    return COMPONENT_BLOCK_PREMIUM;
50	  }
51	  return count * basePremium;
52	};
53	
54	const totalBasePremiumFor = (items: Item[]): number =>
55	  [...countByType(items)].reduce(
56	    (total, [type, count]) => total + premiumForGroup(type, count),
57	    0,
58	  );
59	
60	const surchargeFor = (
61	  items: Item[],
62	  applies: (item: Item) => boolean,
63	  rate: number,
64	): number =>
65	  items
66	    .filter(applies)
67	    .reduce(
68	      (surcharge, item) => surcharge + basePremiumFor(item.type) * rate,
69	      0,
70	    );
71	
72	const CURSE_SURCHARGE_RATE = 0.5;
73	
74	const curseSurchargeFor = (items: Item[]): number =>
75	  surchargeFor(items, (item) => item.cursed === true, CURSE_SURCHARGE_RATE);
76	
77	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	
80	const isHighlyEnchanted = (item: Item): boolean =>
81	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
82	
83	const highEnchantmentSurchargeFor = (items: Item[]): number =>
84	  surchargeFor(items, isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_RATE);
85	
86	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
87	
88	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
89	  policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
90	
91	const LOYALTY_DISCOUNT_RATE = 0.2;
92	const LOYALTY_YEARS_THRESHOLD = 2;
93	
94	const loyaltyDiscountFor = (
95	  customer: Customer,
96	  policyBasePremium: number,
97	): number =>
98	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
99	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
100	    : 0;
101	
102	export type QuoteOptions = {
103	  contractNumber?: number;
104	};
105	
106	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
107	const FIRST_CONTRACT_NUMBER = 1;
108	
109	const followUpDiscountFor = (
110	  options: QuoteOptions | undefined,
111	  policyBasePremium: number,
112	): number =>
113	  (options?.contractNumber ?? FIRST_CONTRACT_NUMBER) > FIRST_CONTRACT_NUMBER
114	    ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE
115	    : 0;
116	
117	export const quote = (
118	  customer: Customer,
119	  items: Item[],
120	  options?: QuoteOptions,
121	): number => {
122	  const policyBasePremium = totalBasePremiumFor(items);
123	  return Math.ceil(
124	    policyBasePremium +
125	      curseSurchargeFor(items) +
126	      highEnchantmentSurchargeFor(items) +
127	      firstInsuranceSurchargeOn(policyBasePremium) -
128	      loyaltyDiscountFor(customer, policyBasePremium) -
129	      followUpDiscountFor(options, policyBasePremium) +
130	      PROCESSING_FEE,
131	  );
132	};
133	
134	export type Damage = {
135	  itemType: string;
136	  amount: number;
137	};
138	
139	export type ClaimResult = {
140	  payout: number;
141	};
142	
143	const DEDUCTIBLE = 100;
144	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
145	const HALF_REIMBURSEMENT_RATE = 0.5;
146	const FULL_REIMBURSEMENT_RATE = 1;
147	
148	const reimbursementRateFor = (item: Item): number =>
149	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
150	    ? HALF_REIMBURSEMENT_RATE
151	    : FULL_REIMBURSEMENT_RATE;
152	
153	export const claim = (policyItems: Item[], damages: Damage[]): ClaimResult => {
154	  const reimbursement = damages[0].amount * reimbursementRateFor(policyItems[0]);
155	  return { payout: reimbursement - DEDUCTIBLE };
156	};
